import java.util.Scanner;
 
public class Main {
    static HashMap<Integer, Integer> memo = new HashMap<>();
    static {
        memo.put(0, 1);
        memo.put(1, 1);
    }
    
    static int countWays(int n) {
        // Check memo first, return cached result if present
        if (memo.containsKey(n)) {
            return memo.get(n);
        }
        
        // Recursively compute, store in memo, and return
        int result = countWays(n - 1) + countWays(n - 2);
        memo.put(n, result);
        return result;
