        Scanner sc = new Scanner(System.in);
        int n = sc.nextInt();
        
        // Validate input (n >= 0)
        if (n < 0) {
            System.out.println("Invalid Input");
            return;
        }
        
        System.out.println("Number of Ways: " + countWays(n));
    }
}

