```java
import java.util.*;
public class Main {
    static final HashMap<Integer,Integer> memo = new HashMap<>();
    static int ways(int n) {
        if (n == 0 || n == 1) return 1;
        if (memo.containsKey(n)) return memo.get(n);
        int answer = ways(n-1) + ways(n-2);
        memo.put(n, answer);
        return answer;
    }
    public static void main(String[] args) {
        Scanner in = new Scanner(System.in);
        int n = in.nextInt();
        if (n < 0) System.out.println("Invalid Input");
        else System.out.println("Number of Ways: " + ways(n));
    }
}
```
